'use client';
import { FormEvent, useEffect, useMemo, useRef, useState } from 'react';
import { tours,categories } from '../data';
import { defaultServices } from '../services-data';
import { defaultStays } from '../lodgings-data';
import { compressImage } from '../lib/image-compression';
import { RichTextEditor } from './rich-text-editor';
import { LogoutLink } from './logout-link';
import { ImageUpload } from './image-upload';
import { CouponManager } from './coupon-manager';

type Row=Record<string,unknown>;
type Booking=Row&{reference:string;tour_slug:string;tour_date:string;customer_name:string;email:string;quantity:number;total:number;status:string};
type AdminUser=Row&{user_id:string;email:string;full_name?:string;order_count?:number;order_total?:number};
const navGroups=[{title:'Transaccional',items:[['overview','Resumen','⌂'],['orders','Pedidos','▤'],['calendar','Calendario','□'],['coupons','Cupones','%'],['users','Usuarios','◉'],['forms','Formularios','✉'],['tour','Tours','⌁'],['service','Servicios','✦'],['lodging','Hospedajes','⌂'],['categories_custom','Categorías','▦'],['destination','Destinos','⛰'],['media','Media','▧'],['reviews','Reseñas','★']]},{title:'General',items:[['post','Blog','¶'],['faq','FAQs','?'],['policy','Políticas','§'],['appearance','Portadas','▣'],['menu','Menú','☰']]}];const nav=navGroups.flatMap(group=>group.items);
const posts=[{slug:'que-llevar-volcan-baru',title:'Qué llevar para subir el Volcán Barú',excerpt:'Una lista práctica para disfrutar el amanecer en la cima.',content:'Guía de preparación para el Volcán Barú.'},{slug:'islas-boca-chica',title:'Boca Chica: islas que tienes que conocer',excerpt:'Playas tranquilas, snorkel y naturaleza.',content:'Guía local de Boca Chica.'},{slug:'cafe-geisha',title:'Por qué el café Geisha es tan especial',excerpt:'Altura y microclimas detrás de una taza excepcional.',content:'Historia del café Geisha panameño.'}];
const faqs=[{question:'¿Cómo reservo un tour?',answer:'Selecciona la fecha y cantidad, agrégalo al carrito y completa tus datos.'},{question:'¿Cómo se paga?',answer:'Por ahora coordinamos el pago en efectivo después de recibir el pedido.'},{question:'¿Qué pasa si llueve?',answer:'La seguridad es prioridad; podemos reprogramar o proponer una alternativa.'}];
const policies=[{name:'Política general de cancelación',content:'Puedes solicitar una reprogramación sin cargo avisando con al menos 72 horas.',is_global:1}];
const demo:Record<string,Row[]>={tour:tours as unknown as Row[],service:defaultServices.map(x=>({...x,price_type:x.priceType})),lodging:defaultStays.map(x=>({...x,price_type:x.priceType,person_price:x.personPrice,group_price:x.groupPrice})),post:posts,policy:policies};
const dbType:Record<string,string>={tour:'tours',service:'services',lodging:'lodgings',post:'posts',faq:'faqs',policy:'policies'};
const rowKey=(tab:string,row:Row)=>String(row.slug??row.question??row.name??row.id);
const label=(tab:string,row:Row)=>String(row.name??row.title??row.question??row.reference??tab);
const publicUrl=(tab:string,row:Row)=>tab==='tour'?`/tours/${row.slug}`:tab==='service'?`/servicios/${row.slug}`:tab==='lodging'?`/hospedajes/${row.slug}`:tab==='post'?`/blog/${row.slug}`:tab==='faq'?'/faqs':'/politicas';
const val=(row:Row|null,...keys:string[])=>{for(const key of keys)if(row?.[key]!=null)return String(row[key]);return ''};

export function AdminDashboard({signOutPath}:{signOutPath:string}){const [tab,setTab]=useState('overview');const [sidebarOpen,setSidebarOpen]=useState(false);const [profileMenuOpen,setProfileMenuOpen]=useState(false);const [sidebarProfileOpen,setSidebarProfileOpen]=useState(false);const [rows,setRows]=useState<Row[]>([]);const [orders,setOrders]=useState<Booking[]>([]);const [orderSort,setOrderSort]=useState<'desc'|'asc'>('desc');const [users,setUsers]=useState<AdminUser[]>([]);const [creatingUser,setCreatingUser]=useState(false);const [selectedUser,setSelectedUser]=useState<(AdminUser&{orders?:Booking[]})|null>(null);const [selectedOrder,setSelectedOrder]=useState<Booking|null>(null);const [editor,setEditor]=useState<Row|null|undefined>(undefined);const [trash,setTrash]=useState(false);const [calendarView,setCalendarView]=useState('list');const [monthCursor,setMonthCursor]=useState<Date>(()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth(),1);});const [message,setMessage]=useState('');const [profile,setProfile]=useState<Row>({});const [cms,setCms]=useState<{pages:Row[];menu:Row[];categories:Record<string,Row[]>;destinations:Row[]}>({pages:[],menu:[],categories:{},destinations:[]});
async function loadContent(kind=tab){if(!dbType[kind])return[];const res=await fetch(`/api/content?type=${dbType[kind]}&includeTombstones=1`,{cache:'no-store'});const data=res.ok?await res.json() as {rows:Row[];tombstones:string[]}:{rows:[],tombstones:[]};const stored=data.rows;const deleted=new Set(data.tombstones);const map=new Map(stored.map(row=>[rowKey(kind,row),row]));const merged=(demo[kind]??[]).filter(row=>!deleted.has(rowKey(kind,row))).map(row=>map.get(rowKey(kind,row))??row);const list=[...merged,...stored.filter(row=>!merged.some(item=>rowKey(kind,item)===rowKey(kind,row)))];setRows(list);return list;}
async function loadOrders(){const res=await fetch('/api/bookings',{cache:'no-store'});if(res.ok)setOrders(await res.json() as Booking[]);}
async function loadUsers(){const res=await fetch('/api/admin/users',{cache:'no-store'});if(res.ok)setUsers(await res.json() as AdminUser[]);}
async function openUser(user:AdminUser){const res=await fetch(`/api/admin/users?userId=${encodeURIComponent(user.user_id)}`,{cache:'no-store'});if(res.ok){const data=await res.json() as {profile:AdminUser;orders:Booking[]};setSelectedUser({...data.profile,orders:data.orders});}}
async function loadCms(){const res=await fetch('/api/admin/cms',{cache:'no-store'});if(res.ok)setCms(await res.json());}
useEffect(()=>{setEditor(undefined);setSelectedOrder(null);setSelectedUser(null);setCreatingUser(false);setTrash(false);setMessage('');if(dbType[tab]){void loadContent(tab);void loadCms();}if(['overview','orders','calendar'].includes(tab))void loadOrders();if(tab==='users')void loadUsers();if(['appearance','menu','categories_custom','destination'].includes(tab))void loadCms();if(tab==='profile')fetch('/api/profile').then(r=>r.json()).then(data=>setProfile(data as Row));},[tab]);useEffect(()=>{void loadOrders();const params=new URLSearchParams(window.location.search);const urlTab=params.get('tab');if(!urlTab||!dbType[urlTab])return;setTab(urlTab);const editSlug=params.get('edit');if(editSlug){void (async()=>{const list=await loadContent(urlTab);const row=list.find(r=>String(r.slug)===editSlug);setEditor(row??null);})();}},[]);
async function upload(file:File){const optimized=await compressImage(file);const data=new FormData();data.append('file',optimized);const res=await fetch('/api/uploads',{method:'POST',body:data});const json=await res.json() as {url?:string;error?:string};if(!res.ok)throw new Error(json.error||'Falló la carga');return json.url!;}
async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();setMessage('Guardando…');const form=event.currentTarget;const data=new FormData(form);if(tab==='tour'){const meta=String(data.get('metaDescription')??'');const keywords=String(data.get('keywords')??'').split(',').map(value=>value.trim()).filter(Boolean);if(meta.length>160){setMessage('La meta descripción no puede superar 160 caracteres.');return}if(keywords.length>8){setMessage('Usa un máximo de 8 palabras clave separadas por comas.');return}}const body={...Object.fromEntries(data.entries()),type:tab} as Row;const cover=data.get('coverFile');if(cover instanceof File&&cover.size)body.coverImage=await upload(cover);const gallery=data.getAll('galleryFiles').filter((x):x is File=>x instanceof File&&x.size>0);if(gallery.length)body.gallery=JSON.stringify(await Promise.all(gallery.map(upload)));if(tab==='service')body.image=body.coverImage||body.image;if(editor&&editor.id)body.id=editor.id;const res=await fetch('/api/content',{method:editor?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const json=await res.json() as {error?:string};setMessage(res.ok?'Cambios guardados y publicados.':json.error??'No se pudo guardar.');if(res.ok){setEditor(undefined);await loadContent(tab);}}
async function updateOrder(reference:string,status:string){const res=await fetch('/api/bookings',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({reference,status})});const data=await res.json() as {order?:Booking;error?:string};if(res.ok&&data.order){setOrders(old=>old.map(order=>order.reference===reference?data.order!:order));setSelectedOrder(old=>old?.reference===reference?data.order!:old);setMessage(`Pedido ${reference} actualizado y notificación generada.`);}else setMessage(data.error??'No se pudo actualizar el pedido.');}
async function deleteOrder(reference:string){if(!confirm(`¿Eliminar el pedido ${reference}? Esta acción no se puede deshacer.`))return;const res=await fetch('/api/bookings',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({reference})});if(res.ok){setOrders(old=>old.filter(order=>order.reference!==reference));if(selectedOrder?.reference===reference)setSelectedOrder(null);setMessage(`Pedido ${reference} eliminado.`);}else{const data=await res.json() as {error?:string};setMessage(data.error??'No se pudo eliminar el pedido.');}}
async function saveOrder(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!selectedOrder)return;setMessage('Guardando pedido…');const data=Object.fromEntries(new FormData(event.currentTarget).entries());const res=await fetch('/api/bookings',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({reference:selectedOrder.reference,...data})});const result=await res.json() as {order?:Booking;error?:string};if(res.ok&&result.order){setOrders(old=>old.map(order=>order.reference===selectedOrder.reference?result.order!:order));setSelectedOrder(result.order);setMessage('Pedido actualizado correctamente.');}else setMessage(result.error??'No se pudo guardar.');}
async function removeContent(row:Row){if(!confirm(`¿Eliminar ${label(tab,row)}? Esta acción no se puede deshacer.`))return;const res=await fetch('/api/content',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({type:tab,id:row.id,key:rowKey(tab,row)})});if(res.ok){setMessage('Registro eliminado.');await loadContent(tab);}else setMessage('No se pudo eliminar el registro.');}
async function archive(row:Row){const res=await fetch('/api/content',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:dbType[tab],slug:String(row.slug??''),id:Number(row.id||0),key:rowKey(tab,row),archive:true})});if(res.ok){setMessage('Movido a la papelera.');await loadContent(tab);}else setMessage('No se pudo archivar.');}
async function restore(row:Row){const res=await fetch('/api/content',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:dbType[tab],slug:String(row.slug??''),id:Number(row.id||0),key:rowKey(tab,row),restore:true})});if(res.ok){setMessage('Restaurado y publicado.');await loadContent(tab);}else setMessage('No se pudo restaurar.');}
async function loadTrash(){const res=await fetch(`/api/content?type=${dbType[tab]}&status=draft`,{cache:'no-store'});if(res.ok)setRows(await res.json() as Row[]);}
async function toggleHome(row:Row){const res=await fetch('/api/content',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:dbType[tab],slug:String(row.slug),toggleHome:true})});if(res.ok)await loadContent(tab);}
async function toggleFaqHome(row:Row){const res=await fetch('/api/content',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:row.id,toggleFaqHome:true})});if(res.ok)await loadContent(tab);}
async function moveFaq(index:number,dir:-1|1){const t=index+dir;if(t<0||t>=rows.length)return;const next=[...rows];[next[index],next[t]]=[next[t],next[index]];const ids=next.filter(r=>Boolean(r.id)).map(r=>Number(r.id));const res=await fetch('/api/content',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({faqReorder:true,ids})});if(res.ok){setRows(next);}else setMessage('No se pudo reordenar.');}
async function markSeen(reference:string){const res=await fetch('/api/bookings',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({action:'mark_seen',reference})});if(res.ok)setOrders(old=>old.map(o=>o.reference===reference?{...o,seen:1}:o));}
const openOrder=(order:Booking)=>{setSelectedOrder(order);void markSeen(order.reference);};
const upcoming=orders.filter(o=>o.status!=='cancelled'&&o.status!=='completed');const total=orders.reduce((sum,o)=>sum+Number(o.total||0),0);const newOrders=orders.filter(o=>!o.seen).length;const sortedOrders=[...orders].sort((a,b)=>orderSort==='desc'?String(b.created_at||'').localeCompare(String(a.created_at||'')):String(a.created_at||'').localeCompare(String(b.created_at||'')));const calendar=useMemo(()=>{const grouped=new Map<string,Booking[]>();orders.forEach(order=>grouped.set(order.tour_date,[...(grouped.get(order.tour_date)??[]),order]));return [...grouped.entries()].sort(([a],[b])=>a.localeCompare(b));},[orders]);
return <div className={`admin-layout${sidebarOpen?' sidebar-open':''}`}><button className="admin-menu-toggle" type="button" aria-label={sidebarOpen?'Cerrar menú administrativo':'Abrir menú administrativo'} aria-expanded={sidebarOpen} onClick={()=>setSidebarOpen(open=>!open)}><span/><span/><span/></button><button className="admin-overlay" type="button" aria-label="Cerrar menú" onClick={()=>setSidebarOpen(false)}/><aside className="admin-sidebar"><button type="button" className="admin-sidebar__brand" onClick={()=>setSidebarProfileOpen(open=>!open)}><span className="admin-dot"/>BONGO <small>ADMIN</small></button>{sidebarProfileOpen&&<div className="admin-sidebar__profile-menu"><button type="button" onClick={()=>{setTab('profile');setSidebarProfileOpen(false);setSidebarOpen(false);}}>◎ Perfil</button><LogoutLink href={signOutPath}>↪ Cerrar sesión</LogoutLink></div>}<a className="admin-view-site" href="/"><span aria-hidden="true">←</span><span>Ver sitio</span></a><nav>{navGroups.map(group=><div key={group.title} className="admin-nav-group"><span className="admin-nav-group__title">{group.title}</span>{group.items.map(([id,name,icon])=><button key={id} className={tab===id?'active':''} onClick={()=>{setTab(id);setSidebarOpen(false)}}><span>{icon}</span>{name}{id==='orders'&&<em className="nav-count">{orders.length}</em>}{id==='orders'&&newOrders>0&&<em className="nav-count nav-count--new">({newOrders})</em>}</button>)}</div>)}</nav></aside><main className="admin-main"><header><div><p>Gestión operativa</p><h1>{nav.find(x=>x[0]===tab)?.[1] ?? (tab==='profile'?'Mi perfil':'')}</h1></div><div className="admin-account"><button type="button" className="admin-avatar" aria-haspopup="menu" aria-expanded={profileMenuOpen} onClick={()=>setProfileMenuOpen(open=>!open)}>BO</button>{profileMenuOpen&&<div className="admin-account__menu" role="menu"><button type="button" role="menuitem" onClick={()=>{setTab('profile');setProfileMenuOpen(false);}}>◎ Perfil</button><LogoutLink href={signOutPath}>↪ Cerrar sesión</LogoutLink></div>}</div></header>
{tab==='overview'&&<><section className="admin-stats"><article><span>Pedidos</span><strong>{orders.length}</strong><small>Histórico total</small></article><article><span>Próximos</span><strong>{upcoming.length}</strong><small>Por atender</small></article><article><span>Ventas registradas</span><strong>${total.toFixed(2)}</strong><small>Pago coordinado en efectivo</small></article></section><section className="admin-list"><div className="admin-list__head"><div><h2>Próximos pedidos</h2><p>Reservas que requieren seguimiento.</p></div><button className="button button--small" onClick={()=>setTab('orders')}>Ver todos</button></div><OrderRows rows={upcoming.slice(0,6)} onUpdate={updateOrder} onOpen={order=>{setTab('orders');setSelectedOrder(order);void markSeen(order.reference);}} onDelete={deleteOrder}/></section><PaymentMethodsManager/></>}
{tab==='orders'&&(selectedOrder?<OrderDetail order={selectedOrder} onSubmit={saveOrder} onBack={()=>setSelectedOrder(null)} message={message} onConfirmCancel={ref=>void updateOrder(ref,'cancelled')}/>:<section className="admin-list"><div className="admin-list__head"><div><h2>Pedidos y reservas</h2><p>Edita clientes, fechas, importes y estados desde un solo lugar.</p></div><div className="admin-list__buttons"><span className="status-pill">{orders.length} pedidos</span><button className="button button--small" type="button" onClick={()=>setOrderSort(s=>s==='desc'?'asc':'desc')}>Fecha {orderSort==='desc'?'↓':'↑'}</button></div></div><OrderRows rows={sortedOrders} onUpdate={updateOrder} onOpen={order=>{setSelectedOrder(order);void markSeen(order.reference);}} onDelete={deleteOrder}/><p role="status" className="admin-message">{message}</p></section>)}
{tab==='calendar'&&(selectedOrder?<OrderDetail order={selectedOrder} onSubmit={saveOrder} onBack={()=>setSelectedOrder(null)} message={message} onConfirmCancel={ref=>void updateOrder(ref,'cancelled')}/>:<section className="admin-list"><div className="admin-list__head"><div><h2>Calendario de salidas</h2><p>Agenda de reservas por fecha. Haz clic en una salida para ver el pedido.</p></div><div className="cal-toolbar"><span className="status-pill">{calendar.length} fechas</span><div className="cal-view-toggle"><button type="button" className={calendarView==='list'?'active':''} onClick={()=>setCalendarView('list')}>Lista</button><button type="button" className={calendarView==='month'?'active':''} onClick={()=>setCalendarView('month')}>Mensual</button><button type="button" className={calendarView==='week'?'active':''} onClick={()=>setCalendarView('week')}>Semanal</button></div></div></div>{calendarView==='month'?<MonthCalendar orders={orders} cursor={monthCursor} onMove={setMonthCursor} onOpen={openOrder}/>:calendarView==='week'?<WeekCalendar orders={orders} cursor={monthCursor} onMove={setMonthCursor} onOpen={openOrder}/>:<div className="admin-calendar">{calendar.length?calendar.map(([date,items])=><article key={date}><time dateTime={date}><b>{new Date(`${date}T12:00:00`).toLocaleDateString('es-PA',{day:'2-digit'})}</b><span>{new Date(`${date}T12:00:00`).toLocaleDateString('es-PA',{month:'short',year:'numeric'})}</span></time><div>{items.map(item=><button key={item.reference} type="button" className="cal-item" onClick={()=>openOrder(item)}><strong>{item.tour_slug.replaceAll('-',' ')}</strong><span>{item.customer_name} · {item.quantity} · {item.reference}</span></button>)}</div></article>):<Empty text="Todavía no hay reservas en el calendario."/>}</div>}</section>)}
{tab==='users'&&(creatingUser?<CreateUser onBack={()=>setCreatingUser(false)} onCreated={async text=>{setMessage(text);setCreatingUser(false);await loadUsers();}}/>:selectedUser?<UserDetail user={selectedUser} onBack={()=>setSelectedUser(null)} onSaved={async text=>{setMessage(text);await loadUsers();}} onDeleted={async()=>{setSelectedUser(null);await loadUsers();}} message={message}/>:<section className="admin-list"><div className="admin-list__head"><div><h2>Usuarios registrados</h2><p>Crea cuentas, edita perfiles y consulta sus pedidos.</p></div><div className="admin-list__buttons"><span className="status-pill">{users.length} usuarios</span><button className="button button--primary button--small" onClick={()=>setCreatingUser(true)}>+ Crear usuario</button></div></div><div className="admin-user-table">{users.length?users.map(user=><article key={user.user_id}><div className="admin-user-avatar">{String(user.full_name||user.email).slice(0,2).toUpperCase()}</div><div><b>{String(user.full_name||'Sin nombre')}</b><span>{user.email}</span><small>Registro: {String(user.created_at||'').slice(0,10)||'—'}</small></div><strong>{Number(user.order_count||0)} pedidos</strong><strong>${Number(user.order_total||0).toFixed(2)}</strong><div className="admin-row-actions"><button onClick={()=>void openUser(user)}>Ver / editar</button></div></article>):<Empty text="Aún no hay perfiles registrados."/>}</div></section>)}
{tab==='appearance'&&<AppearanceManager rows={cms.pages} upload={upload} reload={loadCms}/>}
{tab==='menu'&&<MenuManager rows={cms.menu} reload={loadCms}/>}
{tab==='destination'&&<DestinationManager rows={cms.destinations} reload={loadCms}/>}
{tab==='categories_custom'&&<CategoryManager groups={cms.categories} reload={loadCms}/>} 
{tab==='coupons'&&<CouponManager/>}
{dbType[tab]&&<>{editor===undefined?<section className="admin-list"><div className="admin-list__head"><div><h2>{trash?'Papelera':'Contenido publicado'}</h2><p>{trash?'Elementos archivados (borrador) que no son visibles al público.':'Incluye el contenido demo visible en el sitio y los registros creados en el panel.'}</p></div><div className="admin-list__buttons"><button className={`button button--small${trash?' active':''}`} onClick={()=>{setTrash(v=>!v);if(!trash)void loadTrash();else void loadContent(tab);}}>{trash?'Volver a publicados':'Papelera'}</button><button className="button button--primary button--small" onClick={()=>{setTrash(false);setEditor(null);}}>+ Agregar nuevo</button></div></div><div className="admin-content-rows">{rows.map((row,index)=><article key={rowKey(tab,row)}><div><b>{label(tab,row)}</b><small>{tab==='faq'?(row.category_name?String(row.category_name):'Sin categoría')+(row.sort_order!=null?` · Orden ${row.sort_order}`:''):(row.slug?`/${tab==='post'?'blog':tab==='lodging'?'hospedajes':tab==='service'?'servicios':'tours'}/${row.slug}`:'Contenido general')}</small></div><div className="admin-row-actions">{trash?<><button onClick={()=>restore(row)}>Restaurar</button><button className="danger" onClick={()=>removeContent(row)}>Eliminar definitivamente</button></>:<>{tab==='tour'&&<button className={`star-toggle${row.show_home?' is-active':''}`} onClick={()=>void toggleHome(row)} aria-label={row.show_home?'Quitar de la home':'Mostrar en la home'} title={row.show_home?'Visible en la home':'Oculto de la home'}>{row.show_home?'★':'☆'}</button>}{tab==='faq'&&<button className={`star-toggle${row.show_home?' is-active':''}`} onClick={()=>void toggleFaqHome(row)} aria-label={row.show_home?'Quitar de la home':'Mostrar en la home'} title={row.show_home?'Visible en la home':'Oculto de la home'}>{row.show_home?'★':'☆'}</button>}{tab==='faq'&&Boolean(row.id)&&<><button className="row-move" onClick={()=>moveFaq(index,-1)} disabled={index===0} aria-label="Subir">↑</button><button className="row-move" onClick={()=>moveFaq(index,1)} disabled={index===rows.length-1} aria-label="Bajar">↓</button></>}<a href={publicUrl(tab,row)} target="_blank" rel="noreferrer">Ver</a><button onClick={()=>setEditor(row)}>Editar</button><button className="danger" onClick={()=>archive(row)}>Archivar</button></>}</div></article>)}</div><p className="admin-message">{message}</p></section>:<Editor tab={tab} row={editor??null} categories={cms.categories[tab]??[]} destinations={cms.destinations} onSubmit={save} onCancel={()=>setEditor(undefined)} message={message}/>}</>}
{tab==='reviews'&&<ReviewsManager/>}{tab==='forms'&&<FormsManager/>}{tab==='media'&&<MediaManager/>}{tab==='profile'&&<ProfileEditor profile={profile} onSaved={setMessage} message={message}/>}</main></div>}

function OrderRows({rows,onUpdate,onOpen,onDelete}:{rows:Booking[];onUpdate:(reference:string,status:string)=>void;onOpen:(order:Booking)=>void;onDelete:(reference:string)=>void}){return <div className="admin-order-table"><div className="admin-order-head"><span>Pedido / Cliente</span><span>Creado</span><span>Fecha del tour</span><span>Total</span><span>Estado</span><span></span></div>{rows.length?rows.map(row=><article key={row.reference}><div><small>{row.reference}</small><b>{row.tour_slug.replaceAll('-',' ')}</b><span>{row.customer_name} · {row.email}</span></div><time>{row.created_at?String(row.created_at).slice(0,10):'—'}</time><time>{row.tour_date}</time><strong>${Number(row.total).toFixed(2)}</strong><select value={row.status} onChange={e=>onUpdate(row.reference,e.target.value)}><option value="pending">Pendiente</option><option value="cancellation_requested">Cancelación solicitada</option><option value="completed">Completado</option><option value="cancelled">Cancelado</option></select><button className="order-view" onClick={()=>onOpen(row)}>Ver pedido</button><button className="danger" onClick={()=>onDelete(row.reference)}>Eliminar</button></article>):<Empty text="Aún no hay pedidos."/>}</div>}
function OrderDetail({order,onSubmit,onBack,message,onConfirmCancel}:{order:Booking;onSubmit:(event:FormEvent<HTMLFormElement>)=>void;onBack:()=>void;message:string;onConfirmCancel:(reference:string)=>void}){return <section className="admin-card order-detail"><button className="admin-back" onClick={onBack}>← Volver a pedidos</button><div className="order-detail__heading"><div><p>Pedido</p><h2>{order.reference}</h2></div><span className="status-pill">{String(order.status).replaceAll('_',' ')}</span></div>{order.status==='cancellation_requested'&&<div className="cancel-confirm-bar"><p>El cliente solicitó cancelar este pedido.</p><button type="button" className="button button--danger" onClick={()=>onConfirmCancel(order.reference)}>Confirmar cancelación</button></div>}<form className="admin-form" onSubmit={onSubmit}><div className="form-row"><label>Cliente<input name="customerName" defaultValue={String(order.customer_name)}/></label><label>Correo<input name="email" type="email" defaultValue={String(order.email)}/></label></div><div className="form-row"><label>Teléfono<input name="phone" defaultValue={String(order.phone??'')}/></label><label>Fecha del tour<input name="tourDate" type="date" defaultValue={String(order.tour_date)}/></label></div><div className="form-row"><label>Cantidad<input name="quantity" type="number" min="1" defaultValue={Number(order.quantity)}/></label><label>Total<input name="total" type="number" min="0" step="0.01" defaultValue={Number(order.total)}/></label></div><div className="form-row"><label>Estado<select name="status" defaultValue={String(order.status)}><option value="pending">Pendiente</option><option value="cancellation_requested">Cancelación solicitada</option><option value="completed">Completado</option><option value="cancelled">Cancelado</option></select></label><label>Método de pago<input value="Contra entrega / efectivo" readOnly/></label></div><label>Notas internas<textarea name="adminNotes" rows={5} defaultValue={String(order.admin_notes??'')}/></label><label>Nota para el cambio de estado<input name="statusNote" placeholder="Ej. disponibilidad confirmada con el guía"/></label><div className="order-detail__summary"><span>Experiencia</span><b>{order.tour_slug.replaceAll('-',' ')}</b><span>Modalidad</span><b>Por {String(order.price_mode)==='group'?'grupo':'persona'}</b></div><div className="admin-form__actions"><span>{message}</span><button className="button button--primary">Actualizar pedido</button></div></form></section>}
function Empty({text}:{text:string}){return <div className="admin-empty"><span>◇</span><p>{text}</p></div>}
function MonthCalendar({orders,cursor,onMove,onOpen}:{orders:Booking[];cursor:Date;onMove:(d:Date)=>void;onOpen:(o:Booking)=>void}){const byDate=new Map<string,Booking[]>();orders.forEach(o=>byDate.set(o.tour_date,[...(byDate.get(o.tour_date)||[]),o]));const year=cursor.getFullYear(),month=cursor.getMonth();const firstDow=new Date(year,month,1).getDay();const days=new Date(year,month+1,0).getDate();const cells:(number|null)[]=[...Array(firstDow).fill(null),...Array.from({length:days},(_,i)=>i+1)];const dow=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];return <div className="cal-month"><div className="cal-month__head"><button type="button" onClick={()=>onMove(new Date(year,month-1,1))}>←</button><b>{cursor.toLocaleDateString('es-PA',{month:'long',year:'numeric'})}</b><button type="button" onClick={()=>onMove(new Date(year,month+1,1))}>→</button></div><div className="cal-month__grid cal-month__grid--dow">{dow.map(d=><span key={d}>{d}</span>)}</div><div className="cal-month__grid">{cells.map((day,i)=>{if(day===null)return <span key={`e-${i}`} className="cal-day is-empty"/>;const iso=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const items=byDate.get(iso)||[];return <div key={day} className={`cal-day${items.length?' has-orders':''}`}><b>{day}</b>{items.length>0&&<span className="cal-day__count">{items.length}</span>}{items.slice(0,2).map(o=><button key={o.reference} type="button" className="cal-item cal-item--small" onClick={()=>onOpen(o)}>{o.tour_slug.replaceAll('-',' ')}</button>)}</div>;})}</div></div>;}
function WeekCalendar({orders,cursor,onMove,onOpen}:{orders:Booking[];cursor:Date;onMove:(d:Date)=>void;onOpen:(o:Booking)=>void}){const byDate=new Map<string,Booking[]>();orders.forEach(o=>byDate.set(o.tour_date,[...(byDate.get(o.tour_date)||[]),o]));const start=new Date(cursor);const dow=(start.getDay()+6)%7;start.setDate(start.getDate()-dow);const days=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d;});const iso=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return <div className="cal-week"><div className="cal-month__head"><button type="button" onClick={()=>{const d=new Date(start);d.setDate(d.getDate()-7);onMove(d);}}>←</button><b>{days[0].toLocaleDateString('es-PA',{day:'numeric',month:'short'})} – {days[6].toLocaleDateString('es-PA',{day:'numeric',month:'short'})}</b><button type="button" onClick={()=>{const d=new Date(start);d.setDate(d.getDate()+7);onMove(d);}}>→</button></div><div className="cal-week__grid">{days.map(d=>{const key=iso(d);const items=byDate.get(key)||[];return <div key={key} className="cal-week__day"><b>{d.toLocaleDateString('es-PA',{weekday:'short'})} {d.getDate()}</b>{items.map(o=><button key={o.reference} type="button" className="cal-item cal-item--small" onClick={()=>onOpen(o)}>{o.tour_slug.replaceAll('-',' ')} · {o.customer_name}</button>)}</div>;})}</div></div>;}
function CreateUser({onBack,onCreated}:{onBack:()=>void;onCreated:(message:string)=>void}){const [status,setStatus]=useState('');async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setStatus('Creando usuario…');const body=Object.fromEntries(new FormData(event.currentTarget).entries());const res=await fetch('/api/admin/users',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const data=await res.json() as {message?:string;error?:string};if(res.ok)onCreated(data.message??'Usuario creado.');else setStatus(data.error??'No se pudo crear el usuario.');}return <section className="admin-card user-detail"><button className="admin-back" onClick={onBack}>← Volver a usuarios</button><div className="admin-card__head"><div><h2>Crear usuario</h2><p>La contraseña temporal debe comunicarse al cliente de forma segura.</p></div></div><form className="admin-form" onSubmit={submit}><div className="form-row"><label>Nombre completo<input name="fullName" required/></label><label>Correo electrónico<input name="email" type="email" required/></label></div><div className="form-row"><label>Contraseña temporal<input name="password" type="password" minLength={8} required/><small>Mínimo 8 caracteres.</small></label><label>Teléfono<input name="phone"/></label></div><div className="form-row"><label>País<input name="country" defaultValue="Panamá"/></label><label>Ciudad<input name="city"/></label></div><div className="admin-form__actions"><span>{status}</span><button className="button button--primary">Crear usuario</button></div></form></section>}
function UserDetail({user,onBack,onSaved,onDeleted,message}:{user:AdminUser&{orders?:Booking[]};onBack:()=>void;onSaved:(message:string)=>void;onDeleted:()=>void;message:string}){async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();onSaved('Guardando usuario…');const form=Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string,unknown>;form.marketingOptIn=form.marketingOptIn==='on';const res=await fetch('/api/admin/users',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({userId:user.user_id,...form})});onSaved(res.ok?'Usuario actualizado correctamente.':'No se pudo actualizar el usuario.');}async function remove(){if(!confirm(`¿Eliminar a ${String(user.full_name||user.email)}? Su acceso quedará bloqueado.`))return;const res=await fetch('/api/admin/users',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({userId:user.user_id})});const data=await res.json() as {error?:string};if(res.ok)onDeleted();else onSaved(data.error??'No se pudo eliminar el usuario.');}return <section className="admin-card user-detail"><button className="admin-back" onClick={onBack}>← Volver a usuarios</button><div className="order-detail__heading"><div><p>Usuario registrado</p><h2>{String(user.full_name||user.email)}</h2><small>{user.email}</small></div><span className="status-pill">{user.orders?.length??0} pedidos</span></div><form className="admin-form" onSubmit={submit}><div className="form-row"><label>Nombre completo<input name="fullName" defaultValue={String(user.full_name??'')}/></label><label>Correo de acceso<input value={user.email} readOnly/><small>El correo de autenticación se administra en Supabase.</small></label></div><div className="form-row"><label>Teléfono<input name="phone" defaultValue={String(user.phone??'')}/></label><label>Ciudad<input name="city" defaultValue={String(user.city??'')}/></label></div><div className="form-row"><label>País<input name="country" defaultValue={String(user.country??'Panamá')}/></label><label>Contacto de emergencia<input name="emergencyContact" defaultValue={String(user.emergency_contact??'')}/></label></div><label className="check"><input name="marketingOptIn" type="checkbox" defaultChecked={Boolean(user.marketing_opt_in)}/> Acepta novedades y ofertas</label><div className="admin-form__actions"><span>{message}</span><div><button className="button button--danger" type="button" onClick={remove}>Eliminar usuario</button><button className="button button--primary">Guardar usuario</button></div></div></form><div className="user-orders"><h3>Pedidos del usuario</h3><div className="user-order-list">{user.orders?.length?user.orders.map(order=><article key={order.reference}><div><small>{order.reference}</small><b>{order.tour_slug.replaceAll('-',' ')}</b><span>{order.tour_date} · {order.quantity} participante(s)</span></div><strong>${Number(order.total).toFixed(2)}</strong><span className="status-pill">{String(order.status).replaceAll('_',' ')}</span></article>):<Empty text="Este usuario no tiene pedidos asociados."/>}</div></div></section>}
function input(name:string,label:string,row:Row|null,...keys:string[]){return <label>{label}<input name={name} defaultValue={val(row,...keys,name)} /></label>}
function SeoField({name,label,row,keys=[],maxLength,help}:{name:string;label:string;row:Row|null;keys?:string[];maxLength:number;help:string}){return <label className="seo-field">{label}<input name={name} maxLength={maxLength} defaultValue={val(row,...keys,name)}/><small>{help}</small></label>}
function Editor({tab,row,categories,destinations,onSubmit,onCancel,message}:{tab:string;row:Row|null;categories:Row[];destinations:Row[];onSubmit:(e:FormEvent<HTMLFormElement>)=>void;onCancel:()=>void;message:string}){const categoryDefault=tab==='post'?val(row,'category_id'):(()=>{const byId=val(row,'category_id');if(byId)return byId;const byName=categories.find(c=>String(c.name)===val(row,'category'));return byName?.id!=null?String(byName.id):''})();const categorySelect=tab==='post'?<BlogCategoryField categories={categories} selected={val(row,'category_id')}/>:<label>Categoría<select name="categoryId" defaultValue={categoryDefault}><option value="">Sin categoría</option>{categories.map(c=><option key={String(c.id)} value={String(c.id)}>{String(c.name)}</option>)}</select></label>;const nameField=tab==='post'?input('title','Título',row):tab==='faq'?input('question','Pregunta',row):input('name','Nombre',row);const slugField=(tab==='tour'||tab==='service'||tab==='lodging'||tab==='post')?input('slug','URL amigable',row):null;return <section className="admin-card"><div className="admin-card__head"><div><button className="admin-back" onClick={onCancel}>← Volver al listado</button><h2>{row?'Editar':'Crear'} contenido</h2><p>Datos principales y publicación a la derecha.</p></div></div><form className="admin-form admin-form--editor" onSubmit={onSubmit}><div className="admin-form__main">
{tab==='tour'&&<><SeoField name="h1" label="H1 para SEO" row={row} maxLength={80} help="Usa un solo H1, claro y descriptivo. Recomendado: 45–70 caracteres e incluir el destino principal."/><SeoField name="metaDescription" label="Meta descripción" row={row} keys={['meta_description']} maxLength={160} help="Resume el tour en 140–160 caracteres (aprox. 20–25 palabras) e incluye una invitación a reservar."/><SeoField name="keywords" label="Palabras clave" row={row} maxLength={250} help="Máximo 8 frases clave relevantes. Sepáralas con coma (,). Ejemplo: tour volcán Barú, tours en Boquete."/><RichTextEditor name="description" label="Descripción" value={val(row,'description','short')}/><label>Destino<select name="destinationId" defaultValue={val(row,'destination_id')}><option value="">Sin destino</option>{destinations.map(d=><option key={String(d.id)} value={String(d.id)}>{String(d.name)}</option>)}</select></label><div className="form-row">{input('location','Lugar',row)}{input('meetingPoint','Punto de encuentro',row,'meeting_point')}</div><div className="form-row">{input('departureTime','Hora de salida',row,'departure_time')}{input('duration','Duración',row)}</div><div className="form-row">{input('difficulty','Dificultad',row)}{input('capacity','Capacidad',row)}</div><label>Modalidad<select name="priceType" defaultValue={val(row,'price_type','priceType')||'person'}><option value="person">Por persona</option><option value="group">Por grupo</option><option value="both">Ambos</option></select></label><div className="form-row">{input('personPrice','Precio/persona',row,'person_price','price')}{input('groupPrice','Precio/grupo',row,'group_price')}</div>{input('seasonPrices','Precios por temporada (JSON)',row,'season_prices')}<label className="check-row"><input type="checkbox" name="priceOnRequest" defaultChecked={val(row,'price_on_request')==='1'}/> Consultar precio (sin precio fijo)</label><ImageUpload name="coverImage" initial={val(row,'cover_image','image')} label="Portada del tour"/><label>Galería<input name="galleryFiles" type="file" accept="image/*" multiple/></label>{['includes','notIncluded','bring','recommendations','prohibited','extraMessages'].map(name=><label key={name}>{({includes:'Qué incluye',notIncluded:'Qué no incluye',bring:'Qué llevar',recommendations:'Recomendaciones',prohibited:'No permitido',extraMessages:'Mensajes extra'} as Record<string,string>)[name]}<textarea name={name} rows={4} defaultValue={Array.isArray(row?.[name])?(row?.[name] as string[]).join('\n'):val(row,name,name.replace(/[A-Z]/g,m=>'_'+m.toLowerCase()))}/></label>)}</>}
{tab==='category'&&<>{input('name','Nombre de categoría',row)}<label>Descripción<textarea name="description" rows={4} defaultValue={val(row,'description')}/></label></>}
{tab==='service'&&<><label>Descripción<textarea name="description" rows={5} defaultValue={val(row,'description')}/></label><div className="form-row">{input('price','Precio',row)}<label>Modalidad<select name="priceType" defaultValue={val(row,'price_type','priceType')||'service'}><option value="service">Por servicio</option><option value="person">Por persona</option><option value="group">Por grupo</option></select></label></div><ImageUpload name="image" initial={val(row,'image')} label="Imagen del servicio"/></>}
{tab==='lodging'&&<>{input('location','Ubicación',row)}<ImageUpload name="image" initial={val(row,'image')} label="Imagen del hospedaje"/><label>Descripción<textarea name="description" rows={4} defaultValue={val(row,'description')}/></label><label>Modalidad<select name="priceType" defaultValue={val(row,'price_type','priceType')||'person'}><option value="person">Por persona</option><option value="group">Por grupo</option><option value="both">Ambos</option></select></label><div className="form-row">{input('personPrice','Precio/persona',row,'person_price')}{input('groupPrice','Precio/grupo',row,'group_price')}</div></>}
{tab==='post'&&<><ImageUpload name="coverImage" initial={val(row,'cover_image','coverImage')} label="Imagen destacada"/><label>Extracto<textarea name="excerpt" rows={3} defaultValue={val(row,'excerpt')} placeholder="Resumen que aparecerá en el listado del blog"/></label><RichTextEditor name="content" label="Contenido del artículo" value={val(row,'content')}/></>}
{tab==='faq'&&<><label>Respuesta<textarea name="answer" rows={5} defaultValue={val(row,'answer')}/></label><label>Orden<input name="sortOrder" type="number" defaultValue={val(row,'sort_order')||'0'}/></label></>}
{tab==='policy'&&<><label>Contenido<textarea name="content" rows={8} defaultValue={val(row,'content')}/></label><label className="check"><input type="checkbox" name="isGlobal" defaultChecked={Boolean(row?.is_global)}/> Usar como política general</label></>}
</div><aside className="admin-form__aside">{nameField}{slugField}{tab!=='policy'&&categorySelect}<div className="admin-form__actions"><span>{message}</span><div><button type="button" className="button" onClick={onCancel}>Cancelar</button><button className="button button--primary">Guardar y publicar</button></div></div></aside></form></section>}



function BlogCategoryField({categories,selected}:{categories:Row[];selected:string}){const [items,setItems]=useState(categories);const [selectedId,setSelectedId]=useState(selected);const [creating,setCreating]=useState(false);const [name,setName]=useState('');const [status,setStatus]=useState('');async function createCategory(){if(!name.trim())return;setStatus('Creando…');const response=await fetch('/api/admin/cms',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'category',entity:'post',name:name.trim(),slug:'',description:'',sortOrder:0})});if(!response.ok){setStatus('No se pudo crear la categoría.');return;}const fresh=await fetch('/api/admin/cms',{cache:'no-store'});const data=await fresh.json() as {categories?:Record<string,Row[]>};const next=data.categories?.post??items;const created=next.find(category=>String(category.name).toLowerCase()===name.trim().toLowerCase());setItems(next);if(created?.id)setSelectedId(String(created.id));setName('');setCreating(false);setStatus('Categoría creada y seleccionada.');}return <div className="inline-category-editor"><div className="inline-category-head"><span>Categoría del blog</span><button type="button" onClick={()=>setCreating(open=>!open)}>{creating?'Cancelar':'+ Crear categoría'}</button></div><select name="categoryId" value={selectedId} onChange={event=>setSelectedId(event.target.value)}><option value="">Sin categoría</option>{items.map(category=><option key={String(category.id)} value={String(category.id)}>{String(category.name)}</option>)}</select>{creating&&<div className="inline-category-create"><input value={name} onChange={event=>setName(event.target.value)} placeholder="Nombre de la nueva categoría"/><button type="button" onClick={createCategory}>Crear y usar</button></div>}<small>{status||'Las categorías del blog son independientes de tours, servicios y hospedajes.'}</small></div>}

function ProfileEditor({profile,onSaved,message}:{profile:Row;onSaved:(m:string)=>void;message:string}){async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();onSaved('Guardando…');const body=Object.fromEntries(new FormData(e.currentTarget).entries());const res=await fetch('/api/profile',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(body)});onSaved(res.ok?'Perfil actualizado correctamente.':'No se pudo guardar.');}return <section className="admin-card"><div className="admin-card__head"><div><h2>Perfil de administrador</h2><p>Edita tus datos de contacto sin cambiar tus permisos administrativos.</p></div></div><form className="admin-form" onSubmit={submit}><div className="form-row">{input('fullName','Nombre completo',profile,'full_name')}{input('phone','Teléfono',profile)}</div><div className="form-row">{input('country','País',profile)}{input('city','Ciudad',profile)}</div>{input('emergencyContact','Contacto de emergencia',profile,'emergency_contact')}<div className="admin-form__actions"><span>{message}</span><button className="button button--primary">Guardar perfil</button></div></form></section>}

const pageDefaults:Record<string,Row>={home:{page_key:'home',eyebrow:'Tours auténticos en Panamá',title:'La aventura empieza donde termina la rutina.',description:'Explora volcanes, islas y bosques con guías locales que conocen cada rincón de Chiriquí.',image:'/images/bongo-hero.png',buttons:'[{"label":"Explorar tours","url":"#tours","style":"primary"},{"label":"Diseña tu aventura","url":"/contacto","style":"glass"}]',meta:'["08° 46′ N","Chiriquí, Panamá","Desde 2013"]'},tours:{page_key:'tours',eyebrow:'Explora Panamá',title:'Encuentra tu próxima aventura.',description:'Experiencias pequeñas, guías locales y paisajes que se quedan contigo.',buttons:'[]',meta:'[]'},services:{page_key:'services',eyebrow:'Complementa la aventura',title:'Servicios que hacen el viaje más fácil.',description:'',buttons:'[]',meta:'[]'},lodgings:{page_key:'lodgings',eyebrow:'Descansa bien',title:'Hospedajes con alma de aventura.',description:'Opciones claras por persona o para tu grupo completo.',buttons:'[]',meta:'[]'},blog:{page_key:'blog',eyebrow:'Historias de ruta',title:'El cuaderno de Bongo.',description:'Ideas honestas y consejos locales para viajar mejor por Panamá.',buttons:'[]',meta:'[]'},faqs:{page_key:'faqs',eyebrow:'Centro de ayuda',title:'Preguntas frecuentes.',description:'Todo lo que necesitas saber antes de vivir la aventura.',buttons:'[]',meta:'[]'},responsabilidad:{page_key:'responsabilidad-social',eyebrow:'Nuestra huella',title:'Turismo que deja algo bueno.',description:'Cuidamos los lugares que compartimos y trabajamos con personas de cada comunidad.',buttons:'[]',meta:'[]',content:'<h2>Local primero</h2><p>Priorizamos guías, transportistas, fincas y pequeños proveedores panameños. Así, una mayor parte de cada reserva permanece en el destino.</p><h2>Grupos pequeños</h2><p>Reducen el impacto, mejoran la seguridad y permiten una experiencia genuinamente cercana.</p><h2>Respeto por la naturaleza</h2><p>Aplicamos principios de no dejar rastro, evitamos plásticos de un solo uso cuando es posible y seguimos las normas de cada área protegida.</p>'},derechos:{page_key:'derechos-de-autor',eyebrow:'Uso responsable',title:'Derechos de autor.',description:'',buttons:'[]',meta:'[]',content:'<p>Los textos, fotografías, identidad visual y materiales publicados en este sitio pertenecen a Bongo Outdoors Tours o se utilizan con autorización de sus titulares.</p><p>No está permitida su reproducción comercial sin consentimiento previo por escrito. Para solicitar autorización, escribe a <a href="mailto:info@bongoutdoors.com">info@bongoutdoors.com</a>.</p>'}};
function parseList(value:unknown,kind:'buttons'|'meta'){try{const rows=JSON.parse(String(value||'[]')) as Array<Record<string,string>>|string[];return kind==='meta'?(rows as string[]).join('\n'):(rows as Array<Record<string,string>>).map(x=>`${x.label}|${x.url}|${x.style||'primary'}`).join('\n')}catch{return ''}}
function AppearanceManager({rows,upload,reload}:{rows:Row[];upload:(file:File)=>Promise<string>;reload:()=>Promise<void>}){const [selected,setSelected]=useState<Row|null>(null);const [status,setStatus]=useState('');const merged=Object.values(pageDefaults).map(base=>rows.find(row=>row.page_key===base.page_key)??base);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setStatus('Guardando…');const data=new FormData(e.currentTarget);let image=String(data.get('image')||'');const file=data.get('coverFile');if(file instanceof File&&file.size)image=await upload(file);const labels=data.getAll('buttonLabel').map(String);const urls=data.getAll('buttonUrl').map(String);const styles=data.getAll('buttonStyle').map(String);const buttons=labels.map((label,index)=>({label,url:urls[index]||'/',style:styles[index]==='glass'?'glass':'primary'})).filter(x=>x.label.trim());const meta=String(data.get('meta')||'').split('\n').map(x=>x.trim()).filter(Boolean);const heroType=String(data.get('heroType')||'image');const heroVideo=String(data.get('heroVideo')||'');const heroSlides=JSON.parse(String(data.get('heroSlides')||'[]'));const tourSort=String(data.get('tourSort')||'manual');const tourOrder=String(data.get('tourOrder')||'[]');const tourCardStyle=String(data.get('tourCardStyle')||'classic');const seoTitle=String(data.get('seoTitle')||'');const seoDescription=String(data.get('seoDescription')||'');const seoKeywords=String(data.get('seoKeywords')||'');const sections=String(data.get('sections')||'{}');const content=String(data.get('content')||'');const body={resource:'page',pageKey:data.get('pageKey'),eyebrow:data.get('eyebrow'),title:data.get('title'),description:data.get('description'),image,buttons:JSON.stringify(buttons),meta:JSON.stringify(meta),heroConfig:JSON.stringify({type:heroType,videoUrl:heroVideo,slides:heroSlides}),tourSort,tourOrder,tourCardStyle,seoTitle,seoDescription,seoKeywords,sections,content};const res=await fetch('/api/admin/cms',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});setStatus(res.ok?'Portada actualizada.':'No se pudo guardar.');if(res.ok){setSelected(null);await reload();}}return selected?<section className="admin-card"><button className="admin-back" onClick={()=>setSelected(null)}>← Volver a portadas</button><h2>Editar portada: {String(selected.page_key)}</h2><form className="admin-form" onSubmit={submit}><input type="hidden" name="pageKey" value={String(selected.page_key)}/>{input('eyebrow','Texto superior',selected)}{input('title','Título principal',selected)}<label>Descripción<textarea name="description" rows={4} defaultValue={val(selected,'description')}/></label>{(selected.page_key==='responsabilidad-social'||selected.page_key==='derechos-de-autor')&&<RichTextEditor name="content" label="Contenido de la página" value={val(selected,'content')}/>}<ImageUpload name="image" initial={val(selected,'image')} label="Foto de banner"/><HeroConfigField value={selected.hero_config}/>{selected.page_key==='home'&&<label className="card-style-field">Diseño de tarjetas de tours<select name="tourCardStyle" defaultValue={val(selected,'tour_card_style')||'classic'}><option value="classic">Clásico (precio abajo)</option><option value="overlay">Sobre la imagen (precio en la foto)</option></select></label>}{selected.page_key==='home'&&<TourOrderField sort={selected.tour_sort} order={selected.tour_order}/>}{selected.page_key==='home'&&<HomeSectionsField value={selected.sections}/>}<div className="form-row">{input('seoTitle','Título SEO (meta title)',selected,'seo_title')}{input('seoKeywords','Palabras clave (separadas por coma)',selected,'seo_keywords')}</div>{input('seoDescription','Meta descripción',selected,'seo_description')}<BannerButtonFields value={selected.buttons}/><label>Datos inferiores, uno por línea<textarea name="meta" rows={4} defaultValue={parseList(selected.meta,'meta')}/></label><div className="admin-form__actions"><span>{status}</span><button className="button button--primary">Guardar portada</button></div></form></section>:<section className="admin-list"><div className="admin-list__head"><div><h2>Portadas y banners</h2><p>Edita foto, texto y cualquier cantidad de botones por página.</p></div></div><div className="admin-content-rows">{merged.map(row=><article key={String(row.page_key)}><div><b>{String(row.title)}</b><small>{String(row.page_key)}</small></div><button onClick={()=>setSelected(row)}>Editar portada →</button></article>)}</div></section>}

function BannerButtonFields({value}:{value:unknown}){let initial:Array<{label:string;url:string;style:string}>=[];try{initial=JSON.parse(String(value||'[]'))}catch{}const [buttons,setButtons]=useState(initial);return <fieldset className="banner-button-editor"><legend>Botones del banner</legend>{buttons.map((button,index)=><div key={index}><input name="buttonLabel" aria-label={`Texto del botón ${index+1}`} value={button.label} onChange={e=>setButtons(old=>old.map((x,i)=>i===index?{...x,label:e.target.value}:x))}/><input name="buttonUrl" aria-label={`Enlace del botón ${index+1}`} value={button.url} onChange={e=>setButtons(old=>old.map((x,i)=>i===index?{...x,url:e.target.value}:x))}/><select name="buttonStyle" aria-label={`Estilo del botón ${index+1}`} value={button.style||'primary'} onChange={e=>setButtons(old=>old.map((x,i)=>i===index?{...x,style:e.target.value}:x))}><option value="primary">Principal</option><option value="glass">Transparente</option></select><button type="button" onClick={()=>setButtons(old=>old.filter((_,i)=>i!==index))}>Eliminar</button></div>)}<button type="button" className="button button--small" onClick={()=>setButtons(old=>[...old,{label:'Nuevo botón',url:'/',style:'primary'}])}>+ Agregar botón</button></fieldset>}

function HeroConfigField({value}:{value:unknown}){let initial:{type:string;videoUrl?:string;slides?:{url:string;duration:number;kenburns:boolean}[]}={type:'image',slides:[]};try{const p=JSON.parse(String(value||'{"type":"image"}'));initial={type:p.type||'image',videoUrl:p.videoUrl||'',slides:Array.isArray(p.slides)?p.slides:[]}}catch{}const [type,setType]=useState(initial.type);const [videoUrl,setVideoUrl]=useState(initial.videoUrl||'');const [slides,setSlides]=useState<{url:string;duration:number;kenburns:boolean}[]>(initial.slides||[]);return <fieldset className="banner-button-editor hero-config-field"><legend>Fondo del banner</legend><input type="hidden" name="heroType" value={type}/><input type="hidden" name="heroVideo" value={videoUrl}/><input type="hidden" name="heroSlides" value={JSON.stringify(slides)}/><label>Tipo de fondo<select value={type} onChange={e=>setType(e.target.value)}><option value="image">Imagen fija</option><option value="slideshow">Imágenes pasando (carrusel)</option><option value="video">Video de fondo</option></select></label>{type==='video'&&<label>URL del video (mp4, YouTube o Vimeo)<input value={videoUrl} onChange={e=>setVideoUrl(e.target.value)} placeholder="https://…/video.mp4 o enlace de YouTube/Vimeo"/></label>}{type==='slideshow'&&<><div className="hero-slides-editor">{slides.map((slide,index)=><div className="hero-slide-row" key={index}><ImageUpload name={`_slide-${index}`} initial={slide.url} label={`Imagen ${index+1}`} onChange={url=>setSlides(old=>old.map((s,i)=>i===index?{...s,url}:s))}/><div className="hero-slide-opts"><label>Duración (s)<input type="number" min="3" value={slide.duration} onChange={e=>setSlides(old=>old.map((s,i)=>i===index?{...s,duration:Number(e.target.value)||5}:s))}/></label><label className="check"><input type="checkbox" checked={Boolean(slide.kenburns)} onChange={e=>setSlides(old=>old.map((s,i)=>i===index?{...s,kenburns:e.target.checked}:s))}/> Ken Burns</label><button type="button" onClick={()=>setSlides(old=>old.filter((_,i)=>i!==index))}>Quitar</button></div></div>)}</div><button type="button" className="button button--small" onClick={()=>setSlides(old=>[...old,{url:'',duration:5,kenburns:true}])}>+ Agregar imagen</button></>}</fieldset>}

function TourOrderField({sort,order}:{sort:unknown;order:unknown}){const [mode,setMode]=useState(String(sort||'manual'));const [tours,setTours]=useState<Row[]>([]);const [list,setList]=useState<string[]>(JSON.parse(String(order||'[]')));useEffect(()=>{fetch('/api/content?type=tours',{cache:'no-store'}).then(r=>r.json()).then(rows=>{const all=rows as Row[];const slugs=all.map(r=>String(r.slug));const merged=list.length?[...list.filter(s=>slugs.includes(s)),...slugs.filter(s=>!list.includes(s))]:slugs;setTours(all);setList(merged);}).catch(()=>{})},[]);function move(index:number,dir:-1|1){const t=index+dir;if(t<0||t>=list.length)return;const next=[...list];[next[index],next[t]]=[next[t],next[index]];setList(next);}return <fieldset className="banner-button-editor hero-config-field"><legend>Orden de tours en la home</legend><input type="hidden" name="tourSort" value={mode}/><input type="hidden" name="tourOrder" value={JSON.stringify(list)}/><label>Ordenar por<select value={mode} onChange={e=>setMode(e.target.value)}><option value="manual">Manual</option><option value="sales">Más vendidos</option><option value="reviews">Con más reseñas</option></select></label>{mode==='manual'&&<div className="tour-order-editor">{list.map((slug,index)=><div className="tour-order-row" key={slug}><b>{String(tours.find(t=>String(t.slug)===slug)?.name??slug)}</b><div className="admin-row-actions"><button type="button" disabled={index===0} onClick={()=>move(index,-1)} aria-label="Subir">↑</button><button type="button" disabled={index===list.length-1} onClick={()=>move(index,1)} aria-label="Bajar">↓</button></div></div>)}</div>}</fieldset>}

function HomeSectionsField({value}:{value:unknown}){const base:any={tours:{eyebrow:'Experiencias inolvidables',title:'Best adventure tours in Chiriquí & Pedasí, Panamá'},categories:{eyebrow:'Encuentra tu plan',title:'Aventuras para tu estilo',intro:'Desde la cima del volcán hasta el azul del Pacífico. Elige cómo quieres vivir Panamá.'},destinations:{eyebrow:'Destinos',title:'Panamá se vive al aire libre.',intro:'Paisajes distintos, una misma energía. Conectamos cada salida con la gente, la cultura y la naturaleza del lugar.'},story:{eyebrow:'Más que un tour',title:'Conocemos el camino. Cuidamos el destino.',text:'Somos una empresa local nacida entre las montañas de Chiriquí. Cada experiencia apoya a guías, comunidades y pequeños negocios de la región.',image:'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1400&q=85',linkUrl:'/responsabilidad-social',linkLabel:'Nuestra historia',stats:[{value:'13+',label:'Años explorando'},{value:'4.9',label:'Valoración promedio'},{value:'8k+',label:'Viajeros felices'}]},reviews:{eyebrow:'Ellos ya lo vivieron',title:'Historias que vuelven con una sonrisa.'},faq:{eyebrow:'Antes de salir',title:'¿Tienes preguntas?',text:'Encuentra respuestas rápidas o escríbenos directamente. Estamos para ayudarte a elegir bien.'}};let initial:any=base;try{const p=JSON.parse(String(value||'{}'));initial={tours:{...base.tours,...(p.tours||{})},categories:{...base.categories,...(p.categories||{})},destinations:{...base.destinations,...(p.destinations||{})},story:{...base.story,...(p.story||{}),stats:Array.isArray(p.story?.stats)?p.story.stats:base.story.stats},reviews:{...base.reviews,...(p.reviews||{})},faq:{...base.faq,...(p.faq||{})}}}catch{}const [s,setS]=useState(initial);const set=(sec:string,field:string)=>(e:any)=>setS((old:any)=>({...old,[sec]:{...old[sec],[field]:e.target.value}}));const groups:any=[['tours','Tours',['eyebrow','title']],['categories','Categorías',['eyebrow','title','intro']],['destinations','Destinos',['eyebrow','title','intro']],['story','Historia',['eyebrow','title','text','linkLabel','linkUrl']],['reviews','Reseñas',['eyebrow','title']],['faq','FAQ',['eyebrow','title','text']]];const labels:any={eyebrow:'Texto superior',title:'Título',intro:'Introducción',text:'Texto',linkLabel:'Texto del botón',linkUrl:'Enlace del botón'};const setStat=(i:number,field:string)=>(e:any)=>setS((old:any)=>{const stats=[...(old.story.stats||[])];stats[i]={...stats[i],[field]:e.target.value};return{...old,story:{...old.story,stats}}});const addStat=()=>setS(old=>({...old,story:{...old.story,stats:[...(old.story.stats||[]),{value:'',label:''}]}}));const removeStat=(i:number)=>setS(old=>({...old,story:{...old.story,stats:(old.story.stats||[]).filter((_:any,x:number)=>x!==i)}}));return <fieldset className="banner-button-editor hero-config-field"><legend>Títulos y textos de la home</legend><input type="hidden" name="sections" value={JSON.stringify(s)}/>{groups.map(([key,label,fields]:any)=><div className="home-section-group" key={key}><b>{label}</b>{fields.map((f:string)=><label key={f}>{labels[f]||f}<input value={s[key][f]} onChange={set(key,f)}/></label>)}{key==='story'&&<><ImageUpload name="storyImage" initial={s.story.image} label="Imagen de la sección" onChange={url=>setS(old=>({...old,story:{...old.story,image:url}}))}/><div className="stats-editor"><b>Estadísticas</b>{(s.story.stats||[]).map((st:any,i:number)=><div className="stats-editor__row" key={i}><input value={st.value} placeholder="Valor (ej. 13+)" onChange={setStat(i,'value')}/><input value={st.label} placeholder="Etiqueta (ej. Años explorando)" onChange={setStat(i,'label')}/><button type="button" className="danger" onClick={()=>removeStat(i)}>×</button></div>)}<button type="button" className="button button--small" onClick={addStat}>+ Agregar estadística</button></div></>}</div>)}</fieldset>;}
function PaymentMethodsManager(){const [methods,setMethods]=useState<{cash:boolean;paguelo:boolean;paypal:boolean}|null>(null);const [status,setStatus]=useState('');async function load(){const res=await fetch('/api/settings',{cache:'no-store'});if(res.ok){const data=await res.json() as {paymentMethods?:{cash:boolean;paguelo:boolean;paypal:boolean}};setMethods(data.paymentMethods??{cash:true,paguelo:true,paypal:true});}}useEffect(()=>{void load()},[]);async function toggle(key:'cash'|'paguelo'|'paypal'){if(!methods)return;const next={...methods,[key]:!methods[key]};setMethods(next);setStatus('Guardando…');const res=await fetch('/api/settings',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({paymentMethods:next})});setStatus(res.ok?'Guardado.':'No se pudo guardar.');if(!res.ok)await load();}const labels:Record<'cash'|'paguelo'|'paypal',string>={cash:'Efectivo contra entrega',paguelo:'Tarjeta (Paguelo Fácil)',paypal:'PayPal'};return <section className="admin-list"><div className="admin-list__head"><div><h2>Métodos de pago</h2><p>Activa o desactiva cada método en el checkout mientras terminas de configurar Paguelo Fácil y PayPal.</p></div><span className="status-pill">{status||'Activos'}</span></div><div className="admin-content-rows">{(['cash','paguelo','paypal'] as const).map(key=>methods?<article key={key}><div><b>{labels[key]}</b><small>{methods[key]?'Habilitado':'Deshabilitado'}</small></div><div className="admin-row-actions"><button className={`star-toggle${methods[key]?' is-active':''}`} onClick={()=>void toggle(key)} aria-pressed={methods[key]}>{methods[key]?'✓':'—'}</button></div></article>:<article key={key}><div><b>{labels[key]}</b><small>Cargando…</small></div></article>)}</div></section>}
function ReviewsManager(){const [rows,setRows]=useState<Row[]>([]);async function load(){const res=await fetch('/api/reviews',{cache:'no-store'});if(res.ok)setRows(await res.json() as Row[]);}useEffect(()=>{void load()},[]);async function toggle(row:Row){await fetch('/api/reviews',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id:row.id,approved:row.approved?0:1})});await load();}async function remove(id:number){if(!confirm('¿Eliminar esta reseña?'))return;await fetch('/api/reviews',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({id})});await load();}const typeLabel=(t:string)=>t==='lodging'?'Hospedaje':t==='service'?'Servicio':'Tour';return <section className="admin-list"><div className="admin-list__head"><div><h2>Reseñas</h2><p>Aprueba para publicar, oculta o elimina. Se muestra el item al que pertenece.</p></div><span className="status-pill">{rows.length} reseñas</span></div><div className="admin-content-rows">{rows.length?rows.map(row=><article key={String(row.id)} className={row.approved?'is-approved':''}><div><b>{'★'.repeat(Math.max(1,Math.min(5,Number(row.rating)||5)))} · {String(row.name)}</b><small>{typeLabel(String(row.item_type||'tour'))} · {String(row.tour_slug)} · {String(row.comment||'').slice(0,120)}</small><span>{row.created_at?new Date(String(row.created_at)).toLocaleString('es-PA'):''} · {row.approved?'Aprobada':'Pendiente'}</span></div><div className="admin-row-actions"><button onClick={()=>toggle(row)}>{row.approved?'Ocultar':'Aprobar'}</button><button className="danger" onClick={()=>remove(Number(row.id))}>Eliminar</button></div></article>):<Empty text="Aún no hay reseñas."/>}</div></section>;}
function FormsManager(){const [rows,setRows]=useState<Row[]>([]);async function load(){const res=await fetch('/api/forms',{cache:'no-store'});if(res.ok)setRows(await res.json() as Row[]);}useEffect(()=>{void load()},[]);async function mark(id:number){await fetch('/api/forms',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id,status:'read'})});await load();}async function remove(id:number){if(!confirm('¿Eliminar este mensaje?'))return;await fetch('/api/forms',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({id})});await load();}return <section className="admin-list"><div className="admin-list__head"><div><h2>Formularios enviados</h2><p>Mensajes recibidos desde el formulario de contacto.</p></div><span className="status-pill">{rows.length} mensajes</span></div><div className="admin-content-rows">{rows.length?rows.map(row=><article key={String(row.id)} className={row.status==='new'?'is-new':''}><div><b>{String(row.name)} · {String(row.email)}</b><small>{String(row.interest||'')} · {String(row.message||'').slice(0,140)}</small><span>{row.created_at?new Date(String(row.created_at)).toLocaleString('es-PA'):''} · {String(row.status)}</span></div><div className="admin-row-actions">{row.status==='new'&&<button onClick={()=>mark(Number(row.id))}>Marcar leído</button>}<button className="danger" onClick={()=>remove(Number(row.id))}>Eliminar</button></div></article>):<Empty text="Aún no hay formularios."/>}</div></section>;}
function MediaManager(){const [files,setFiles]=useState<Array<{key:string;name:string;alt:string;size:number;uploaded:string;contentType:string}>>([]);const [typeFilter,setTypeFilter]=useState('all');const [sort,setSort]=useState<'new'|'old'>('new');const [search,setSearch]=useState('');const [busy,setBusy]=useState(false);const [status,setStatus]=useState('');const [selected,setSelected]=useState<Set<string>>(new Set());const [viewing,setViewing]=useState<{key:string;name:string;alt:string;isImage:boolean}|null>(null);const inputRef=useRef<HTMLInputElement>(null);async function load(){const res=await fetch('/api/uploads',{cache:'no-store'});if(res.ok){const data=await res.json() as {files:typeof files};setFiles(data.files||[]);}}useEffect(()=>{void load()},[]);async function uploadFiles(list:FileList|File[]){setBusy(true);setStatus('Subiendo…');for(const file of Array.from(list)){const data=new FormData();data.append('file',file);await fetch('/api/uploads',{method:'POST',body:data});}setBusy(false);setStatus('');await load();}async function remove(keys:string[]){if(!keys.length)return;if(!confirm(`¿Eliminar ${keys.length} archivo${keys.length===1?'':'s'}?`))return;const res=await fetch('/api/uploads',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({keys})});if(res.ok){setSelected(new Set());await load();}else setStatus('No se pudo eliminar.');}async function saveMeta(){if(!viewing)return;const res=await fetch('/api/uploads',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({key:viewing.key,name:viewing.name,alt:viewing.alt})});if(res.ok){setStatus('Guardado.');await load();setViewing(null);}else setStatus('No se pudo guardar.');}const kind=(f:{contentType:string;name:string})=>f.contentType.startsWith('image/')||/\.(png|jpe?g|webp|gif|avif|svg|bmp)$/i.test(f.name)?'image':f.contentType.startsWith('video/')||/\.(mp4|webm|mov|m4v|avi)$/i.test(f.name)?'video':'other';const toggle=(key:string)=>setSelected(old=>{const n=new Set(old);n.has(key)?n.delete(key):n.add(key);return n;});const filtered=files.filter(f=>(typeFilter==='all'||kind(f)===typeFilter)&&(!search||f.name.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>sort==='new'?b.uploaded.localeCompare(a.uploaded):a.uploaded.localeCompare(b.uploaded));const open=(f:any)=>setViewing({key:f.key,name:f.name,alt:f.alt,isImage:kind(f)==='image'});return <section className="admin-list"><div className="admin-list__head"><div><h2>Biblioteca de medios</h2><p>Selecciona para borrar en lote, o haz click para ver y editar.</p></div><div className="admin-list__buttons"><button type="button" className="button button--primary button--small" onClick={()=>inputRef.current?.click()}>{busy?'Subiendo…':'+ Subir archivos'}</button>{selected.size>0&&<><button type="button" className="button button--small" onClick={()=>setSelected(new Set())}>Cancelar</button><button type="button" className="button button--small" onClick={()=>void remove([...selected])}>Eliminar {selected.size}</button></>}</div><input ref={inputRef} type="file" accept="image/*,video/*" multiple hidden onChange={e=>{if(e.target.files?.length)void uploadFiles(e.target.files);e.target.value='';}}/></div><div className="media-toolbar"><div className="cal-view-toggle"><button type="button" className={typeFilter==='all'?'active':''} onClick={()=>setTypeFilter('all')}>Todos</button><button type="button" className={typeFilter==='image'?'active':''} onClick={()=>setTypeFilter('image')}>Imágenes</button><button type="button" className={typeFilter==='video'?'active':''} onClick={()=>setTypeFilter('video')}>Videos</button><button type="button" className={typeFilter==='other'?'active':''} onClick={()=>setTypeFilter('other')}>Otros</button></div><input className="media-search" placeholder="Buscar por nombre…" value={search} onChange={e=>setSearch(e.target.value)}/><button type="button" className="button button--small" onClick={()=>setSort(sort==='new'?'old':'new')}>{sort==='new'?'Más recientes':'Más antiguos'}</button></div>{status&&<p className="admin-message">{status}</p>}<div className="media-grid">{filtered.length?filtered.map(f=><figure key={f.key} className={`media-card${selected.has(f.key)?' is-selected':''}`}><div className="media-card__preview" onClick={()=>open(f)}>{kind(f)==='image'?<img src={`/api/files/${f.key}`} alt={f.alt||f.name} loading="lazy"/>:<div className="media-card__icon">{kind(f)==='video'?'▶':'·'}</div>}</div><figcaption><b title={f.name}>{f.name}</b><small>{kind(f)} · {f.uploaded?new Date(f.uploaded).toLocaleDateString('es-PA'):''} · {(f.size/1024).toFixed(0)} KB</small></figcaption><label className="media-card__check"><input type="checkbox" checked={selected.has(f.key)} onChange={()=>toggle(f.key)}/></label><button type="button" className="media-card__delete" onClick={()=>void remove([f.key])} aria-label={`Eliminar ${f.name}`}>×</button></figure>):<Empty text="No hay archivos."/>}</div>{viewing&&<div className="media-lightbox" onClick={()=>setViewing(null)}><div className="media-lightbox__panel" onClick={e=>e.stopPropagation()}><button type="button" className="media-lightbox__close" onClick={()=>setViewing(null)}>×</button>{viewing.isImage?<img src={`/api/files/${viewing.key}`} alt={viewing.alt||viewing.name}/>:<div className="media-card__icon">▶</div>}<div className="media-lightbox__fields"><label>Nombre<input value={viewing.name} onChange={e=>setViewing({...viewing,name:e.target.value})}/></label><label>Texto alternativo (alt)<input value={viewing.alt} onChange={e=>setViewing({...viewing,alt:e.target.value})}/></label><button type="button" className="button button--primary button--small" onClick={()=>void saveMeta()}>Guardar</button></div></div></div>}</section>;}
function MenuManager({rows,reload}:{rows:Row[];reload:()=>Promise<void>}){const [selected,setSelected]=useState<Row|null|undefined>(undefined);const [status,setStatus]=useState('');const [order,setOrder]=useState<Row[]>(rows);useEffect(()=>setOrder([...rows].sort((a,b)=>Number(a.sort_order)-Number(b.sort_order))),[rows]);const roots=order.filter(r=>!r.parent_id);const childrenOf=(id:number)=>order.filter(r=>Number(r.parent_id)===id);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());const res=await fetch('/api/admin/cms',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'menu',...data,id:selected?.id,openNewTab:data.openNewTab==='on'})});setStatus(res.ok?'Elemento guardado.':'No se pudo guardar.');if(res.ok){setSelected(undefined);await reload();}}async function remove(id:unknown){if(!confirm('¿Eliminar este elemento del menú?'))return;const res=await fetch('/api/admin/cms',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'menu',id})});if(res.ok)await reload();}async function reorder(list:Row[],index:number,dir:-1|1){const t=index+dir;if(t<0||t>=list.length)return;const a=list[index],b=list[t];setOrder(prev=>{const p=[...prev];const ia=p.findIndex(x=>x.id===a.id);const ib=p.findIndex(x=>x.id===b.id);if(ia>=0&&ib>=0)[p[ia],p[ib]]=[p[ib],p[ia]];return p;});const next=[...list];[next[index],next[t]]=[next[t],next[index]];const ids=next.filter(r=>r.id!=null).map(r=>Number(r.id));const res=await fetch('/api/admin/cms',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'menu-order',items:ids.map((id,i)=>({id,sort_order:i}))})});if(!res.ok)setStatus('No se pudo reordenar.');}function renderTree(list:Row[],depth:number,parentLabel?:string){return list.map((row,index)=><div key={String(row.id)}><article className={depth>0?'is-child':''}><div><b>{String(row.label)}</b><small>{String(row.url)}</small>{depth>0&&parentLabel&&<span className="menu-parent-badge">↳ de {parentLabel}</span>}</div><div className="admin-row-actions"><button disabled={index===0} onClick={()=>void reorder(list,index,-1)} aria-label="Subir">↑</button><button disabled={index===list.length-1} onClick={()=>void reorder(list,index,1)} aria-label="Bajar">↓</button><button onClick={()=>setSelected(row)}>Editar</button><button className="danger" onClick={()=>remove(row.id)}>Eliminar</button></div></article>{renderTree(childrenOf(Number(row.id)),depth+1,String(row.label))}</div>);}return selected!==undefined?<section className="admin-card"><button className="admin-back" onClick={()=>setSelected(undefined)}>← Volver al menú</button><h2>{selected?'Editar':'Agregar'} elemento</h2><form className="admin-form" onSubmit={submit}><div className="form-row">{input('label','Texto',selected??null)}{input('url','Enlace',selected??null)}</div><label>Elemento padre<select name="parentId" defaultValue={val(selected??null,'parent_id')||''}><option value="">Sin padre (nivel principal)</option>{roots.filter(r=>r.id!==selected?.id).map(r=><option key={String(r.id)} value={String(r.id)}>{String(r.label)}</option>)}</select></label><div className="form-row"><label>Orden<input name="sortOrder" type="number" defaultValue={val(selected??null,'sort_order')||'0'}/></label><label className="check"><input name="openNewTab" type="checkbox" defaultChecked={Boolean(selected?.open_new_tab)}/> Abrir en otra pestaña</label></div><div className="admin-form__actions"><span>{status}</span><button className="button button--primary">Guardar elemento</button></div></form></section>:<section className="admin-list"><div className="admin-list__head"><div><h2>Estructura del menú</h2><p>Reordena con ↑↓. Usa «Editar» para elegir el elemento padre y crear submenús.</p></div><button className="button button--primary button--small" onClick={()=>setSelected(null)}>+ Agregar item</button></div><div className="menu-manager">{roots.length?renderTree(roots,0):<Empty text="Sin elementos."/>}</div><p className="admin-message">{status}</p></section>}

const categoryNames:Record<string,string>={tour:'Tours',service:'Servicios',lodging:'Hospedajes',post:'Blog',faq:'FAQs'};
function CategoryManager({groups,reload}:{groups:Record<string,Row[]>;reload:()=>Promise<void>}){const [entity,setEntity]=useState('tour');const [selected,setSelected]=useState<Row|null|undefined>(undefined);const [status,setStatus]=useState('');const builtIns=entity==='tour'?(categories as unknown as Row[]):[];const stored=groups[entity]??[];const list=[...builtIns.filter(x=>!stored.some(y=>String(y.slug)===String(x.slug))),...stored];async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());const res=await fetch('/api/admin/cms',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'category',entity,...data,id:selected?.id})});setStatus(res.ok?'Categoría guardada.':'No se pudo guardar.');if(res.ok){setSelected(undefined);await reload();}}async function remove(id:unknown){if(!confirm('¿Eliminar esta categoría? Los contenidos conservarán sus datos, pero quedarán sin categoría.'))return;const res=await fetch('/api/admin/cms',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'category',entity,id})});if(res.ok)await reload();}async function toggleHome(row:Row){const res=await fetch('/api/admin/cms',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'category-toggle',entity,id:row.id})});if(res.ok)await reload();}return selected!==undefined?<section className="admin-card"><button className="admin-back" onClick={()=>setSelected(undefined)}>← Volver a categorías</button><h2>{selected?'Editar':'Crear'} categoría de {categoryNames[entity]}</h2><form className="admin-form" onSubmit={submit}>{input('name','Nombre',selected??null)}{entity!=='faq'&&input('slug','URL amigable',selected??null)}{entity==='tour'&&<ImageUpload name="image" initial={val(selected??null,'image')} label="Imagen de la categoría"/>}<label>Descripción<textarea name="description" rows={4} defaultValue={val(selected??null,'description')}/></label><label>Orden<input name="sortOrder" type="number" defaultValue={val(selected??null,'sort_order')||'0'}/></label><div className="admin-form__actions"><span>{status}</span><button className="button button--primary">Guardar categoría</button></div></form></section>:<section className="admin-list"><div className="admin-list__head"><div><h2>Categorías independientes</h2><p>Cada módulo usa su propia clasificación; nunca se mezclan.</p></div><button className="button button--primary button--small" onClick={()=>setSelected(null)}>+ Agregar categoría</button></div><div className="admin-module-tabs">{Object.entries(categoryNames).map(([key,name])=><button className={entity===key?'active':''} key={key} onClick={()=>setEntity(key)}>{name}</button>)}</div><div className="admin-content-rows">{list.map(row=><article key={rowKey(entity,row)}><div><b>{String(row.name)}</b><small>{categoryNames[entity]}</small></div><div className="admin-row-actions">{entity==='tour'&&Boolean(row.id)&&<button className={`star-toggle${row.show_home?' is-active':''}`} onClick={()=>toggleHome(row)} aria-label={row.show_home?'Quitar de la home':'Mostrar en la home'} title={row.show_home?'Visible en la home':'Oculto de la home'}>{row.show_home?'★':'☆'}</button>}<button onClick={()=>setSelected(row)}>Editar</button>{Boolean(row.id)&&<button className="danger" onClick={()=>remove(row.id)}>Eliminar</button>}</div></article>)}</div></section>}
function DestinationManager({rows,reload}:{rows:Row[];reload:()=>Promise<void>}){const [selected,setSelected]=useState<Row|null|undefined>(undefined);const [status,setStatus]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget).entries());const res=await fetch('/api/admin/cms',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'destination',...data,id:selected?.id})});setStatus(res.ok?'Destino guardado.':'No se pudo guardar.');if(res.ok){setSelected(undefined);await reload();}}async function remove(id:unknown){if(!confirm('¿Eliminar este destino? Los tours conservarán sus datos, pero quedarán sin destino.'))return;const res=await fetch('/api/admin/cms',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({resource:'destination',id})});if(res.ok)await reload();}return selected!==undefined?<section className="admin-card"><button className="admin-back" onClick={()=>setSelected(undefined)}>← Volver a destinos</button><h2>{selected?'Editar':'Crear'} destino</h2><form className="admin-form" onSubmit={submit}>{input('name','Nombre',selected??null)}{input('slug','URL amigable',selected??null)}<label>Descripción<textarea name="description" rows={4} defaultValue={val(selected??null,'description')}/></label><label>Orden<input name="sortOrder" type="number" defaultValue={val(selected??null,'sort_order')||'0'}/></label><div className="admin-form__actions"><span>{status}</span><button className="button button--primary">Guardar destino</button></div></form></section>:<section className="admin-list"><div className="admin-list__head"><div><h2>Destinos</h2><p>Seleccionables desde el editor de tours para filtrar por destino en la web.</p></div><button className="button button--primary button--small" onClick={()=>setSelected(null)}>+ Agregar destino</button></div><div className="admin-content-rows">{rows.map(row=><article key={String(row.id)}><div><b>{String(row.name)}</b><small>{row.slug?`/tours?destino=${row.slug}`:'Sin slug'}</small></div><div className="admin-row-actions"><button onClick={()=>setSelected(row)}>Editar</button><button className="danger" onClick={()=>remove(row.id)}>Eliminar</button></div></article>)}</div><p className="admin-message">{status}</p></section>}
